sys_script_include.script:
var Requested_Date__48_hours = Class.create();
Requested_Date__48_hours.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getDays: function() {
    var requestDate = this.getParameter('sysparm_date');
	var gdtRequest = new GlideDateTime(requestDate);
	var newDate= new GlideDateTime();
    newDate.add("48:00:00"); 
      if(gdtRequest.compareTo(newDate)<0) {
         return 'requested date should be atleast 48 hours in the future';
      }
      return '';
}
});
